      role1 = 2182000,
      role2 = 201106,
      role3 = 201201,
      role5 = 2182404,
      roleanim = 1.1,
      sentence = "When there's no end in sight, you have a hard time figuring out where you are, or even being sure if you're moving forward at all.",
