    },
    [57] = {
      beijing = 1351,
      dialog = 3,
      music = "206_XM_Weddingdress",
      renwu = "npc",
      sentence = "Hearing this answer, I didn't feel the least bit surprised. Rather, I felt moved.",
      next = {58}
    },
    [58] = {
      beijing = 1351,
      dialog = 3,
      music = "206_XM_Weddingdress",
      renwu = "npc",
      sentence = "I didn't know how Lucien moved forward in that lightless ocean. My imagination failed me.",
      next = {59}
    },
    [59] = {
      beijing = 1351,
      dialog = 3,
      music = "206_XM_Weddingdress",
      renwu = "npc",
      sentence = "That place was a flat, calm expanse with no lighthouse, no reefs or shoals, and aside from the water below, perhaps a few drifting clouds.",
      next = {60}
    },
    [60] = {
      beijing = 1351,
      dialog = 3,
      music = "206_XM_Weddingdress",
      renwu = "npc",
      sentence = "All he could do was move forward to the beat of his own drum, with only intuition and instinct to guide him in a search for one little speck of light after another amidst the desolate emptiness.",
      next = {61}
    },
    [61] = {
      beijing = 1351,
      dialog = 3,
      music = "206_XM_Weddingdress",
      renwu = "npc",
      sentence = "Points of light to look toward for the rest of us as we move forward.",
