    },
    [63] = {
      beijing = 1351,
      dialog = 3,
      music = "206_XM_Weddingdress",
      renwu = "npc",
      sentence = "Not far away, someone was wakeboarding on the water. A speedboat zipped along, but the person on the wakeboard clinging to the rope lost their balance and fell into the water, sending up an epic splash.",
