      role1 = 2182000,
      role2 = 201106,
      role3 = 201204,
      role5 = 2182404,
      roleanim = 1.2,
      sentence = "You're smarter than anyone—and more determined too—which is why you look so beautiful cutting through the water. Once someone sets their eyes on you, they just can't look away.",
      next = {69}
    },
    [69] = {
      beijing = 1351,
