      role1 = 2182000,
      role2 = 201105,
      role3 = 201204,
      role5 = 2182404,
      roleanim = 1.2,
      sentence = "I wanted to be like you. Determined, unflinching, forever striving for some far-flung dream. I want to be that beautiful too.",
